import{c as a,Q as s,j as e,m as l}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Skills 九大類別與 Analytics Agent 設計指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/33-skills-nine-categories.md","filePath":"research/best-practices/33-skills-nine-categories.md","lastUpdated":1780842316000}'),n={name:"research/best-practices/33-skills-nine-categories.md"};function i(r,t,o,d,c,h){return s(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="skills-九大類別與-analytics-agent-設計指南" tabindex="-1">Skills 九大類別與 Analytics Agent 設計指南 <a class="header-anchor" href="#skills-九大類別與-analytics-agent-設計指南" aria-label="Permalink to &quot;Skills 九大類別與 Analytics Agent 設計指南&quot;">​</a></h1><blockquote><p>來源：</p><ul><li><a href="https://claude.com/blog/lessons-from-building-claude-code-how-we-use-skills" target="_blank" rel="noreferrer">Lessons from building Claude Code: How we use skills</a>（2026-06-03）</li><li><a href="https://claude.com/blog/how-anthropic-enables-self-service-data-analytics-with-claude" target="_blank" rel="noreferrer">How Anthropic enables self-service data analytics with Claude</a>（2026-06-03）<br> 整理日期：2026-06-05</li></ul></blockquote><hr><h2 id="九大-skill-類別-anthropic-內部分類" tabindex="-1">九大 Skill 類別（Anthropic 內部分類） <a class="header-anchor" href="#九大-skill-類別-anthropic-內部分類" aria-label="Permalink to &quot;九大 Skill 類別（Anthropic 內部分類）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>類別</th><th>說明</th><th>範例</th></tr></thead><tbody><tr><td>1</td><td><strong>Library &amp; API Reference</strong></td><td>內部/外部函式庫文件，含 edge case 和 gotchas</td><td>內部 SDK 使用、第三方 API 怪癖</td></tr><tr><td>2</td><td><strong>Product Verification</strong></td><td>測試與驗證流程，可量化品質影響</td><td>功能測試、UI 驗收</td></tr><tr><td>3</td><td><strong>Data Fetching &amp; Analysis</strong></td><td>連接資料與監控基礎架構</td><td>DB 查詢、指標取得</td></tr><tr><td>4</td><td><strong>Business Process Automation</strong></td><td>重複工作流自動化為單一指令</td><td>日報生成、審批流</td></tr><tr><td>5</td><td><strong>Code Scaffolding &amp; Templates</strong></td><td>框架樣板 + 自然語言需求</td><td>新服務初始化、API endpoint 生成</td></tr><tr><td>6</td><td><strong>Code Quality &amp; Review</strong></td><td>品質強制與 code review 輔助</td><td>風格檢查、PR review</td></tr><tr><td>7</td><td><strong>CI/CD &amp; Deployment</strong></td><td>程式碼管理與部署協調</td><td>自動部署、rollback</td></tr><tr><td>8</td><td><strong>Runbooks</strong></td><td>多工具調查工作流 → 結構化報告</td><td>事件處理 SOP、on-call 指南</td></tr><tr><td>9</td><td><strong>Infrastructure Operations</strong></td><td>日常維護與操作程序</td><td>資源清理、健康檢查</td></tr></tbody></table><hr><h2 id="skill-設計核心原則" tabindex="-1">Skill 設計核心原則 <a class="header-anchor" href="#skill-設計核心原則" aria-label="Permalink to &quot;Skill 設計核心原則&quot;">​</a></h2><h3 id="避免的常見錯誤" tabindex="-1">避免的常見錯誤 <a class="header-anchor" href="#避免的常見錯誤" aria-label="Permalink to &quot;避免的常見錯誤&quot;">​</a></h3><blockquote><p>&quot;A skill that restates what Claude would do by default adds context without adding value.&quot;</p></blockquote><ul><li><strong>不要</strong>重述 Claude 預設就會做的事</li><li><strong>不要</strong>過度指定指令（限制 Claude 靈活性）</li><li><strong>不要</strong>只做 markdown 文件（Skill 是完整資料夾：腳本、模板、資源）</li></ul><h3 id="必做的事" tabindex="-1">必做的事 <a class="header-anchor" href="#必做的事" aria-label="Permalink to &quot;必做的事&quot;">​</a></h3><ul><li>從實際失敗點累積「Gotchas」section</li><li>用 progressive disclosure（巢狀子檔案）逐步揭露 context</li><li>description 針對模型決策，不是人類閱讀</li></ul><h3 id="進階功能" tabindex="-1">進階功能 <a class="header-anchor" href="#進階功能" aria-label="Permalink to &quot;進階功能&quot;">​</a></h3><ul><li><strong>On-demand hooks</strong>：依情況觸發工具（PreToolUse 守護破壞性操作）</li><li><strong>Assets 資料夾</strong>：輸出生成用的模板</li><li><strong>Persistent storage</strong>：<code>\${CLAUDE_PLUGIN_DATA}</code> 跨 session 記憶</li><li><strong>Execution logs</strong>：讓 agent 參考之前的工作記錄</li></ul><hr><h2 id="skill-資料夾結構" tabindex="-1">Skill 資料夾結構 <a class="header-anchor" href="#skill-資料夾結構" aria-label="Permalink to &quot;Skill 資料夾結構&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-skill/</span></span>
<span class="line"><span>├── SKILL.md         # 主指令（含 description、Gotchas、Trigger conditions）</span></span>
<span class="line"><span>├── config.json      # 使用者特定 context 設定</span></span>
<span class="line"><span>├── assets/          # 輸出模板</span></span>
<span class="line"><span>├── scripts/         # 可重複使用腳本（組合 &gt; 樣板重建）</span></span>
<span class="line"><span>└── logs/            # 執行歷史（透過 \${CLAUDE_PLUGIN_DATA}）</span></span></code></pre></div><hr><h2 id="analytics-agent-特殊設計模式" tabindex="-1">Analytics Agent 特殊設計模式 <a class="header-anchor" href="#analytics-agent-特殊設計模式" aria-label="Permalink to &quot;Analytics Agent 特殊設計模式&quot;">​</a></h2><p>Analytics agent 與 coding agent 有根本差異：有「唯一正確答案」，失敗模式不同。</p><h3 id="三大失敗模式" tabindex="-1">三大失敗模式 <a class="header-anchor" href="#三大失敗模式" aria-label="Permalink to &quot;三大失敗模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失敗模式</th><th>說明</th><th>解法</th></tr></thead><tbody><tr><td>概念模糊</td><td>&quot;active users&quot; → 多個候選欄位</td><td>Semantic layer 消除歧義</td></tr><tr><td>資料過期</td><td>Schema、定義持續變動</td><td>元資料視為產品維護</td></tr><tr><td>檢索失敗</td><td>正確資料存在但找不到</td><td>Skills 提升可發現性</td></tr></tbody></table><h3 id="準確率對比" tabindex="-1">準確率對比 <a class="header-anchor" href="#準確率對比" aria-label="Permalink to &quot;準確率對比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置</th><th>準確率</th></tr></thead><tbody><tr><td>無 Skills</td><td>≤21%</td></tr><tr><td>有 Skills</td><td>≥95%</td></tr><tr><td>加入 adversarial review sub-agent</td><td>+6%（但 +32% 延遲）</td></tr></tbody></table><h3 id="四層-analytics-stack" tabindex="-1">四層 Analytics Stack <a class="header-anchor" href="#四層-analytics-stack" aria-label="Permalink to &quot;四層 Analytics Stack&quot;">​</a></h3><ol><li><strong>Data Foundations</strong> — Canonical datasets、強制標準、colocated artifacts、metadata-as-product</li><li><strong>Sources of Truth</strong> — Semantic layer、lineage graphs、query corpora、business context</li><li><strong>Skills</strong> — 領域知識 skill + unbook（程序 skill）配對</li><li><strong>Validation</strong> — 離線 eval、ablation study、線上監控、adversarial review</li></ol><h3 id="skills-配對模式" tabindex="-1">Skills 配對模式 <a class="header-anchor" href="#skills-配對模式" aria-label="Permalink to &quot;Skills 配對模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知識 Skill（Knowledge Router）</span></span>
<span class="line"><span>  → 薄層，路由到正確 unbook</span></span>
<span class="line"><span>  → 記錄：概念、grain、exclusions、gotchas、模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>程序 Skill（Unbook）</span></span>
<span class="line"><span>  → 詳細步驟，含 SQL 範例和錯誤處理</span></span>
<span class="line"><span>  → 與 transformation code 共置（data PR 自動同步）</span></span></code></pre></div><h3 id="ci-整合" tabindex="-1">CI 整合 <a class="header-anchor" href="#ci-整合" aria-label="Permalink to &quot;CI 整合&quot;">​</a></h3><p>~90% 的 data PR 現在包含 skill 修改；CI flag 會在模型修改但未更新文件時報警。</p><hr><h2 id="發布與擴散" tabindex="-1">發布與擴散 <a class="header-anchor" href="#發布與擴散" aria-label="Permalink to &quot;發布與擴散&quot;">​</a></h2><p><strong>內部實踐：</strong></p><ul><li>直接 commit 至 <code>./.claude/skills/</code></li><li>內部 plugin marketplace 跨團隊共享</li><li>Sandbox 資料夾有機採用 → 達到一定使用量後升級為官方</li></ul><p><strong>使用量追蹤：</strong> 透過 <code>PreToolUse</code> hook 記錄 skill 呼叫次數，識別高人氣和低使用率 skill。</p>`,35)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
